      manager.hashCode ^
      me.hashCode ^
      path.hashCode ^
      away.hashCode ^
      through.hashCode ^
      waitingForKey.hashCode ^
      fingerprint.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UiMember &&
          runtimeType == other.runtimeType &&
          person == other.person &&
          rank == other.rank &&
          manager == other.manager &&
          me == other.me &&
          path == other.path &&
          away == other.away &&
          through == other.through &&
          waitingForKey == other.waitingForKey &&
          fingerprint == other.fingerprint;
}

